sys_variable_value.value:
/**
 * Writes the matching bfd_case_communication timeline row for an outbound
 * message through the reusable bfd_CommsLogger script include.
 */
(function execute(inputs, outputs) {
    outputs.communication = new bfd_CommsLogger().logOutbound(
        inputs.caseSysId,
        inputs.channel,
        inputs.subject,
        inputs.message,
        inputs.triggeredBy
    );
})(inputs, outputs);

